pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockTime, uint256 senderSeed) public {
        // Ensure block.timestamp can be set via vm.warp
        vm.warp(blockTime);
        // Set pastBlockTime to block.timestamp by first calling fallback
        // but we need to ensure the call succeeds: block.timestamp > pastBlockTime initially (pastBlockTime = 0)
        // So first call with block.timestamp > 0 will succeed and set pastBlockTime = blockTime
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");
        // After this call, pastBlockTime == block.timestamp (if success)
        // Now call again: require(block.timestamp > pastBlockTime) in reference should revert because equal
        // In mutant, require(block.timestamp >= pastBlockTime) would pass
        // We warp to same time (blockTime) again
        vm.warp(blockTime);
        vm.deal(address(this), 10 ether);
        (bool success2, ) = address(c).call{value: 10 ether}("");
        // In reference C, this second call reverts (success2 == false)
        assertTrue(!success2);
    }
}

