pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Ensure we meet the require(msg.value == 10 ether) in reference (or 5 ether in mutant)
        vm.assume(amount == 10 ether);

        // Set initial block conditions so the fallback progresses
        vm.warp(block.timestamp + 1);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Get current block number to check if it's divisible by 15
        uint256 blockNumber = block.number;

        // Send ether via fallback
        (bool success, ) = address(c).call{value: amount}("");

        // If call succeeded (which it should with correct amount), check balance change
        if (success) {
            uint256 balanceAfter = address(c).balance;
            // If block number is not divisible by 15, balance should stay the same
            // (because the transfer inside if(block.number % 15 == 0) won't execute)
            if (blockNumber % 15 != 0) {
                assertTrue(balanceAfter == balanceBefore, "Balance should not decrease when block number not divisible by 15");
            }
            // If block number is divisible by 15, balance may decrease due to transfer
        }
    }
}

