pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 blockNumber, uint256 blockTimestamp) public {
        // Bound inputs to reasonable values
        amount = bound(amount, 0, 100 ether);
        blockNumber = bound(blockNumber, 1, 10000);
        blockTimestamp = bound(blockTimestamp, 1, 1000000);

        // Ensure the fallback call will pass the timestamp check
        // We need pastBlockTime to be less than blockTimestamp. We set it via a previous call with a lower timestamp.
        vm.warp(blockTimestamp - 1);
        vm.deal(address(c), amount);

        // Make a call to set pastBlockTime
        (bool success1,) = address(c).call{value: 0 ether}("");
        vm.assume(success1);

        // Now perform the actual test call at target block number and timestamp
        vm.warp(blockTimestamp);
        vm.roll(blockNumber);

        uint256 balanceBefore = address(c).balance;

        // Call fallback with the fuzzed amount
        (bool success2,) = address(c).call{value: amount}("");

        if (success2) {
            // If successful, balance should have increased by amount (since no transfer occurs if block.number % 15 != 0)
            // Actually the contract only transfers if block.number % 15 == 0
            if (blockNumber % 15 == 0) {
                // Transfer happens: balance increases by (amount - (total balance at that point))
                // The contract transfers whole balance, so final balance is amount (the msg.value just added)
                // But actually it transfers before adding? No, transfer happens in same call after checks
                // So the contract's balance after call = balanceBefore + amount - (balanceBefore + amount) = 0
                // Because it transfers the entire balance
                // But only if it has enough? It transfers address(this).balance
                // So balance after = 0
                assertTrue(address(c).balance == 0);
            } else {
                // No transfer, balance increases by amount
                assertTrue(address(c).balance == balanceBefore + amount);
            }
        } else {
            // Revert case: balance unchanged
            assertTrue(address(c).balance == balanceBefore);
        }
    }
}

