pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockOffset) public {
        vm.assume(blockOffset < 15);

        // Record balance before call
        uint256 balanceBefore = address(c).balance;

        // Set block number to a non-multiple of 15
        vm.roll(block.number - (block.number % 15) + blockOffset);
        vm.warp(block.timestamp + 1);

        // Send exactly 10 ether to trigger fallback
        (bool success,) = address(c).call{value: 10 ether}("");

        // If block number is not multiple of 15, balance should remain
        uint256 balanceAfter = address(c).balance;

        assertTrue(
            (blockOffset == 0 && balanceAfter == 0) || 
            (blockOffset != 0 && balanceAfter == balanceBefore + 10 ether)
        );
    }
}

