pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestampIncrement, uint256 blockNumOffset) public {
        // Ensure timestamp moves forward and block number can be manipulated for the rule
        vm.assume(timestampIncrement > 0 && timestampIncrement < 100000);

        // Set block number to a value where 15 does not divide it initially
        uint256 targetBlock = block.number + (15 - (block.number % 15)) + blockNumOffset % 15;
        vm.roll(targetBlock);
        vm.warp(block.timestamp + timestampIncrement);

        // Make the fallback call with exactly 10 ether
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Ensure the call succeeded
        assertTrue(success);

        // The general rule: if block.number % 15 == 0 after the call, balance must be zero
        // Because the reference contract transfers all balance when that condition holds
        if (block.number % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            // When not divisible by 15, balance should be exactly 10 ether
            assertTrue(address(c).balance == 10 ether);
        }
    }
}

